-- #138 운영 공지 고정 영역 (ADR-0069 decision 2 #45-8, decision 4 #138). Generated by
-- `drizzle-kit generate`, then hand-edited where marked: this header and the tail. The snapshot is
-- as generated.
--
-- - notices: one row per notice an operator wrote — the required title, the body of the posts'
--   editor with its text and images derived when written, '수정됨' as a time, and the pin: a time
--   and one of three slots, unique, so the database holds «최대 3개» whoever writes. No author:
--   a notice is shown as 운영팀's, and who wrote, edited, pinned or unpinned it is admin_actions'.
-- - notice_revisions: every version an edit replaced, for operators only (no UPDATE below).
-- - notice_images: which notice an upload belongs to (one notice per image, as post_images).
CREATE TABLE "notice_images" (
	"notice_id" uuid NOT NULL,
	"media_id" uuid NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "notice_images_notice_id_media_id_pk" PRIMARY KEY("notice_id","media_id"),
	CONSTRAINT "notice_images_media_id_unique" UNIQUE("media_id")
);
--> statement-breakpoint
CREATE TABLE "notice_revisions" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"notice_id" uuid NOT NULL,
	"title" varchar(100) NOT NULL,
	"body" jsonb NOT NULL,
	"body_text" text NOT NULL,
	"image_ids" uuid[] NOT NULL,
	"written_at" timestamp (3) with time zone NOT NULL,
	"replaced_at" timestamp (3) with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "notices" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"title" varchar(100) NOT NULL,
	"body" jsonb NOT NULL,
	"body_text" text NOT NULL,
	"image_ids" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"edited_at" timestamp (3) with time zone,
	"pinned_at" timestamp (3) with time zone,
	"pin_slot" smallint,
	CONSTRAINT "notices_pin_slot_unique" UNIQUE("pin_slot"),
	CONSTRAINT "notices_title_check" CHECK (btrim("notices"."title") <> ''),
	CONSTRAINT "notices_pin_slot_check" CHECK ("notices"."pin_slot" BETWEEN 1 AND 3),
	CONSTRAINT "notices_pinned_check" CHECK (("notices"."pinned_at" IS NULL) = ("notices"."pin_slot" IS NULL))
);
